import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type {
  JournalVoucherNo7Part3Column,
  JournalVoucherNo7Part3Row,
} from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './NhatKyChungTuSo7Phan3Page.module.css';

const TEST_ID = 'rpt-nkct-so-7-phan-3';
const PAGE_ID = 'baocao-nhat-ky-chung-tu-so-7-phan-3';
const TITLE = 'Nhật ký chứng từ  số 7 - Phần 3';
const TITLE_EN = 'Journal voucher No 7 - Part 3';
const PART_LOCK = '703';

type RowTag = 'GrandTotal' | 'Detail';

const PLACEHOLDER_COLUMNS: JournalVoucherNo7Part3Column[] = [
  { key: 'debitAccountCode', kind: 'fixed', headerVi: 'TK Nợ', headerEn: 'Debit a/c' },
  { key: 'debitAccountName', kind: 'fixed', headerVi: 'Tên TK', headerEn: 'Debit name' },
  { key: 'rowTotal', kind: 'total', headerVi: 'Tổng cộng', headerEn: 'Total' },
];

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(raw: JournalVoucherNo7Part3Row['rowTag'], isBold?: boolean): RowTag {
  if (raw === 'GrandTotal') return 'GrandTotal';
  if (raw === 'Detail') return 'Detail';
  if (isBold) return 'GrandTotal';
  return 'Detail';
}

function normalizeItems(items: JournalVoucherNo7Part3Row[]): JournalVoucherNo7Part3Row[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isBold);
    return {
      ...r,
      rowTag,
      isBold: rowTag === 'GrandTotal' || Boolean(r.isBold),
      debitAccountCode: r.debitAccountCode ?? null,
      debitAccountName: r.debitAccountName ?? null,
      creditBuckets: r.creditBuckets ?? {},
      rowTotal: Number(r.rowTotal ?? 0),
    };
  });
}

function creditCodeOf(col: JournalVoucherNo7Part3Column): string {
  if (col.creditAccountCode) return col.creditAccountCode;
  if (col.key?.startsWith('C')) return col.key.slice(1).replace(/_/g, '.');
  return '';
}

const NhatKyChungTuSo7Phan3Page: React.FC = () => {
  const dispatch = useAppDispatch();
  const initial = monthStartEnd();

  const [fromDate, setFromDate] = useState(initial.fromDate);
  const [toDate, setToDate] = useState(initial.toDate);
  const [journalPartCode] = useState(PART_LOCK);
  const [columns, setColumns] = useState<JournalVoucherNo7Part3Column[]>(PLACEHOLDER_COLUMNS);
  const [items, setItems] = useState<JournalVoucherNo7Part3Row[]>([]);
  const [metaGrandTotal, setMetaGrandTotal] = useState<number | null>(null);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const displayColumns = hasViewed && columns.length > 0 ? columns : PLACEHOLDER_COLUMNS;

  const summaryGrandTotal = useMemo(() => {
    if (!hasViewed) return null;
    if (metaGrandTotal != null) return metaGrandTotal;
    const gt = items.find(r => mapRowTag(r.rowTag, r.isBold) === 'GrandTotal');
    return gt ? Number(gt.rowTotal ?? 0) : null;
  }, [hasViewed, items, metaGrandTotal]);

  const detailCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isBold) === 'Detail').length,
    [items],
  );

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim() || !toDate.trim()) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (toDate < fromDate) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    const part = (journalPartCode || PART_LOCK).trim() || PART_LOCK;

    setLoading(true);
    analyticsService
      .getJournalVoucherNo7Part3({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        journalPartCode: part === PART_LOCK ? PART_LOCK : PART_LOCK,
        pageSize: 0,
      })
      .then(report => {
        const nextCols =
          Array.isArray(report.columns) && report.columns.length > 0
            ? report.columns
            : PLACEHOLDER_COLUMNS;
        setColumns(nextCols);
        setItems(normalizeItems(report.items ?? []));
        const metaTotal = report.meta?.rowGrandTotal;
        setMetaGrandTotal(metaTotal != null ? Number(metaTotal) : null);
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được nhật ký chứng từ số 7 Phần 3'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dispatch, fromDate, journalPartCode, toDate]);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedFrom || !appliedTo) return;
    const fileName = `nhat-ky-chung-tu-so-7-phan-3_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/journal-voucher-no7-part3/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        journalPartCode: PART_LOCK,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    if (!hasViewed || loading) return;
    window.print();
  }, [hasViewed, loading]);

  const onFilterKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'exportExcel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: !hasViewed || loading,
        onClick: handleExport,
      },
      {
        id: 'exportPrint',
        action: 'print',
        placement: 'right',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [handleExport, handlePrint, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)}`
      : TITLE_EN;

  const listBody = (
    <>
      {hasViewed ? (
        <p className={styles.subtitle} data-testid={`${TEST_ID}-subtitle`}>
          {subtitle}
        </p>
      ) : null}
      <div className={styles.gridScroll} data-testid={`${TEST_ID}-grid-scroll`}>
        <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
          <thead>
            <tr>
              {displayColumns.map(col => {
                const creditCode = col.kind === 'credit' ? creditCodeOf(col) : '';
                const testId =
                  col.kind === 'credit'
                    ? `${TEST_ID}-col-credit-${creditCode || col.key}`
                    : `${TEST_ID}-col-${col.key}`;
                return (
                  <th
                    key={col.key}
                    data-testid={testId}
                    data-credit-account={creditCode || undefined}
                  >
                    {col.headerVi || col.key}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {items.map((row, index) => {
              const rowTag = mapRowTag(row.rowTag, row.isBold);
              const tone =
                rowTag === 'GrandTotal' ? styles.rowToneGrandTotal : styles.rowToneDetail;
              return (
                <tr
                  key={`${rowTag}|${row.debitAccountCode ?? 'GT'}|${index}`}
                  className={tone}
                  data-testid={`${TEST_ID}-row-${index}`}
                  data-row-tag={rowTag}
                  data-debit-account={row.debitAccountCode ?? ''}
                  data-is-bold={row.isBold ? '1' : '0'}
                >
                  {displayColumns.map(col => {
                    if (col.key === 'debitAccountCode') {
                      const label =
                        rowTag === 'GrandTotal'
                          ? 'Tổng cộng'
                          : (row.debitAccountCode ?? '');
                      return (
                        <td key={col.key} data-testid={`${TEST_ID}-cell-${index}-${col.key}`}>
                          {label}
                        </td>
                      );
                    }
                    if (col.key === 'debitAccountName') {
                      return (
                        <td key={col.key} data-testid={`${TEST_ID}-cell-${index}-${col.key}`}>
                          {row.debitAccountName ?? ''}
                        </td>
                      );
                    }
                    if (col.kind === 'credit') {
                      const code = creditCodeOf(col);
                      const amount = Number(row.creditBuckets?.[code] ?? 0);
                      return (
                        <td
                          key={col.key}
                          className={styles.cellMoney}
                          data-testid={`${TEST_ID}-cell-${index}-${col.key}`}
                        >
                          {formatVnd(amount)}
                        </td>
                      );
                    }
                    if (col.kind === 'total' || col.key === 'rowTotal') {
                      return (
                        <td
                          key={col.key}
                          className={`${styles.cellTotal} ${styles.cellMoney}`}
                          data-testid={`${TEST_ID}-cell-${index}-rowTotal`}
                        >
                          {formatVnd(Number(row.rowTotal ?? 0))}
                        </td>
                      );
                    }
                    return (
                      <td key={col.key} data-testid={`${TEST_ID}-cell-${index}-${col.key}`}>
                        {''}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {!hasViewed && !loading ? (
        <p className={styles.emptyHint}>Chọn khoảng ngày và bấm Xem</p>
      ) : null}
      {hasViewed && detailCount === 0 ? (
        <p className={styles.emptyHint} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </p>
      ) : null}
    </>
  );

  const footer =
    hasViewed && summaryGrandTotal != null ? (
      <div className={styles.summary} data-testid={`${TEST_ID}-summary`}>
        Tổng cộng: {formatVnd(summaryGrandTotal)}
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-file-invoice' }}
        listTitle={TITLE}
        filterMaxWidthPx={1400}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{ testIdPrefix: TEST_ID, profile: 'report', actions: toolbarActions }}
        footer={footer}
        filters={(
          <>
            <Input
              type="date"
              label="Từ ngày"
              value={fromDate}
              onChange={e => setFromDate(e.target.value)}
              onKeyDown={onFilterKeyDown}
              data-testid={`${TEST_ID}-field-fromDate`}
            />
            <Input
              type="date"
              label="Đến ngày"
              value={toDate}
              onChange={e => setToDate(e.target.value)}
              onKeyDown={onFilterKeyDown}
              data-testid={`${TEST_ID}-field-toDate`}
            />
            <div
              className={styles.partLockBadge}
              data-testid={`${TEST_ID}-field-journalPartCode`}
              title="Loại nhật ký 703 (số 7 - Phần 3)"
            >
              Part: <strong>{PART_LOCK}</strong>
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default NhatKyChungTuSo7Phan3Page;
